description:
Implement a `useScrollY` hook that returns the current vertical scroll position (`window.scrollY`) and updates it whenever the user scrolls.

**Example:**
```tsx
const scrollY = useScrollY();
return <header className={scrollY > 50 ? 'sticky' : ''}>...</header>;
```

starter_code:
import { useEffect, useState } from 'react';

export function useScrollY(): number {
  // your code here
}

test_suite:
test('returns a number', () => {
  const { result } = renderHook(() => useScrollY());
  expect(typeof result.current).toBe('number');
});

test('returns 0 when scrollY is 0', () => {
  Object.defineProperty(window, 'scrollY', { writable: true, configurable: true, value: 0 });
  const { result } = renderHook(() => useScrollY());
  expect(result.current).toBe(0);
});

test('updates when scroll event fires', () => {
  Object.defineProperty(window, 'scrollY', { writable: true, configurable: true, value: 0 });
  const { result } = renderHook(() => useScrollY());
  act(() => {
    Object.defineProperty(window, 'scrollY', { writable: true, configurable: true, value: 250 });
    window.dispatchEvent(new Event('scroll'));
  });
  expect(result.current).toBe(250);
});

// __hidden__
test('removes scroll listener on unmount', () => {
  const spy = vi.spyOn(window, 'removeEventListener');
  const { unmount } = renderHook(() => useScrollY());
  unmount();
  expect(spy).toHaveBeenCalledWith('scroll', expect.any(Function));
  spy.mockRestore();
});

solution:
import { useEffect, useState } from 'react';

export function useScrollY(): number {
  const [scrollY, setScrollY] = useState(window.scrollY);

  useEffect(() => {
    const handler = () => setScrollY(window.scrollY);
    window.addEventListener('scroll', handler);
    return () => window.removeEventListener('scroll', handler);
  }, []);

  return scrollY;
}
